/*
 * Embed the LVGL binary UI fonts (generated by lv_font_conv, committed under
 * openrtx/fonts/) directly into flash via .incbin, one blob per fontSize_t.
 * The paths resolve relative to the build directory (a sibling of the repo
 * root, matching voicePromptData.S). Colour displays get the 4bpp anti-aliased
 * set, monochrome the compact 1bpp set, chosen by the CONFIG_FONT_AA define
 * that meson sets for RGB565 targets (hwconfig.h can't be included here — it
 * contains C — so the pixel format is passed in as a -D flag instead).
 */

.section .note.GNU-stack,""
.section .rodata

.macro FONT_BLOB name, path
.global _font_\name\()_start
.global _font_\name\()_end
_font_\name\()_start:
    .incbin "\path"
.set _font_\name\()_end, .
.endm

#ifdef CONFIG_FONT_AA
FONT_BLOB 5,  "../openrtx/fonts/ubuntu_5_4.bin"
FONT_BLOB 6,  "../openrtx/fonts/ubuntu_6_4.bin"
FONT_BLOB 8,  "../openrtx/fonts/ubuntu_8_4.bin"
FONT_BLOB 9,  "../openrtx/fonts/ubuntu_9_4.bin"
FONT_BLOB 10, "../openrtx/fonts/ubuntu_10_4.bin"
FONT_BLOB 12, "../openrtx/fonts/ubuntu_12_4.bin"
FONT_BLOB 16, "../openrtx/fonts/ubuntu_16_4.bin"
#else
FONT_BLOB 5,  "../openrtx/fonts/ubuntu_5_1.bin"
FONT_BLOB 6,  "../openrtx/fonts/ubuntu_6_1.bin"
FONT_BLOB 8,  "../openrtx/fonts/ubuntu_8_1.bin"
FONT_BLOB 9,  "../openrtx/fonts/ubuntu_9_1.bin"
FONT_BLOB 10, "../openrtx/fonts/ubuntu_10_1.bin"
FONT_BLOB 12, "../openrtx/fonts/ubuntu_12_1.bin"
FONT_BLOB 16, "../openrtx/fonts/ubuntu_16_1.bin"
#endif
